// Title: How to verify that an SVG chart’s viewBox matches the original worksheet size using Aspose.Cells in C#
// Common Searches: Aspose.Cells C# render chart to SVG and check viewBox dimensions | compare SVG viewBox size with Excel chart size using Aspose.Cells | C# extract viewBox attribute from SVG generated by Aspose.Cells | set desired size for SVG output with ImageOrPrintOptions and validate dimensions | ensure SVG viewBox matches worksheet dimensions in Aspose.Cells C# code
// Tags: Aspose.Cells chart to SVG viewBox validation | ImageOrPrintOptions SetDesiredSize SVG output | C# extract SVG viewBox attribute | compare worksheet dimensions with SVG viewBox | render Excel chart as SVG Aspose.Cells

using System;
using System.IO;
using System.Xml.Linq;
using Aspose.Cells;
using Aspose.Cells.Charts;
using Aspose.Cells.Rendering;

// The example loads (or creates) a workbook, renders the first chart to an in‑memory SVG using ImageOrPrintOptions with a specified width and height, reads the SVG's viewBox attribute, parses its width and height values, and compares them to the desired dimensions, reporting success when they match and failure otherwise.
class Program
{
    static void Main()
    {
        try
        {
            // Path to a sample workbook (will be created if it does not exist)
            const string workbookPath = "sample.xlsx";

            // Create a workbook with sample data and a chart if the file is missing
            if (!File.Exists(workbookPath))
            {
                CreateSampleWorkbook(workbookPath);
            }

            // Load the workbook
            Workbook workbook = new Workbook(workbookPath);
            Worksheet sheet = workbook.Worksheets[0];

            // Ensure there is at least one chart
            if (sheet.Charts.Count == 0)
            {
                Console.WriteLine("No chart found in the worksheet.");
                return;
            }

            // Use the first chart for validation
            Chart chart = sheet.Charts[0];

            // Desired dimensions for the SVG output (in pixels)
            const int desiredWidth = 800;
            const int desiredHeight = 600;

            // Configure rendering options for SVG
            ImageOrPrintOptions options = new ImageOrPrintOptions
            {
                ImageType = Aspose.Cells.Drawing.ImageType.Svg,
                OnePagePerSheet = true
            };
            // Set the desired size – this influences the viewBox of the generated SVG
            options.SetDesiredSize(desiredWidth, desiredHeight, false);

            // Render the chart to an in‑memory SVG
            using (MemoryStream svgStream = new MemoryStream())
            {
                chart.ToImage(svgStream, options);
                svgStream.Position = 0;

                // Load SVG XML
                XDocument svgDoc = XDocument.Load(svgStream);
                XElement svgRoot = svgDoc.Root;
                if (svgRoot == null)
                {
                    Console.WriteLine("Failed to load SVG root element.");
                    return;
                }

                // Extract the viewBox attribute
                XAttribute viewBoxAttr = svgRoot.Attribute("viewBox");
                if (viewBoxAttr == null)
                {
                    Console.WriteLine("SVG does not contain a viewBox attribute.");
                    return;
                }

                string viewBox = viewBoxAttr.Value;
                Console.WriteLine($"Extracted viewBox: {viewBox}");

                // Parse viewBox values (expected format: "minX minY width height")
                string[] parts = viewBox.Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries);
                if (parts.Length != 4)
                {
                    Console.WriteLine("Unexpected viewBox format.");
                    return;
                }

                // Convert width and height to double
                if (!double.TryParse(parts[2], out double vbWidth) ||
                    !double.TryParse(parts[3], out double vbHeight))
                {
                    Console.WriteLine("Unable to parse viewBox dimensions.");
                    return;
                }

                // Validate dimensions against the desired size
                bool widthMatches = Math.Abs(vbWidth - desiredWidth) < 0.01;
                bool heightMatches = Math.Abs(vbHeight - desiredHeight) < 0.01;

                if (widthMatches && heightMatches)
                {
                    Console.WriteLine("SUCCESS: viewBox dimensions match the original worksheet size.");
                }
                else
                {
                    Console.WriteLine("FAILURE: viewBox dimensions do NOT match the expected size.");
                    Console.WriteLine($"Expected: {desiredWidth} x {desiredHeight}");
                    Console.WriteLine($"Actual:   {vbWidth} x {vbHeight}");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private static void CreateSampleWorkbook(string path)
    {
        try
        {
            Workbook wb = new Workbook();
            Worksheet ws = wb.Worksheets[0];

            // Populate sample data
            ws.Cells["A1"].PutValue("Category");
            ws.Cells["B1"].PutValue("Value");
            ws.Cells["A2"].PutValue("A");
            ws.Cells["B2"].PutValue(10);
            ws.Cells["A3"].PutValue("B");
            ws.Cells["B3"].PutValue(20);
            ws.Cells["A4"].PutValue("C");
            ws.Cells["B4"].PutValue(30);

            // Add a column chart
            int chartIndex = ws.Charts.Add(ChartType.Column, 5, 0, 15, 5);
            Chart chart = ws.Charts[chartIndex];
            chart.NSeries.Add("B2:B4", true);
            chart.NSeries.CategoryData = "A2:A4";

            // Save workbook
            wb.Save(path, SaveFormat.Xlsx);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to create sample workbook: {ex.Message}");
        }
    }
}
